/** Independent Relay key is generated by local Node, never by browser. */
const result = document.querySelector("#result");
async function scenario(mode) {
  const worker = new Worker(new URL("../browser/relay-independent.worker.mjs", import.meta.url), { type: "module" });
  try {
    return await new Promise((resolve, reject) => {
      const id = mode + 1;
      const timer = setTimeout(() => { clean(); reject(Error("independent_worker_timeout")); }, 21000);
      const onMsg = ({ data }) => {
        if (data?.id !== id) return;
        clean();
        if (data.ok) resolve(data);
        else reject(Error(data.error || "independent_worker_failed"));
      };
      const onError = () => { clean(); reject(Error("independent_worker_load_failed")); };
      function clean() {
        clearTimeout(timer);
        worker.removeEventListener("message", onMsg);
        worker.removeEventListener("error", onError);
      }
      worker.addEventListener("message", onMsg);
      worker.addEventListener("error", onError);
      worker.postMessage({ id, action: "RUN", mode });
    });
  } finally { worker.terminate(); }
}
(async () => {
  for (const mode of [0, 1, 2, 3]) {
    const x = await scenario(mode);
    if (x.sends < 1 || x.recvs < 1 || !x.noPeerOnline ||
        ((mode <= 1) !== (x.closed === 0))) {
      throw Error("independent_relay_mode_failed_" + mode);
    }
  }
  result.dataset.state = "passed";
  result.textContent = "PASS: browser Toxcore authenticated Node-owned independent local Relay keys";
})().catch(error => {
  result.dataset.state = "failed";
  result.textContent = "FAIL: " + String(error?.message || error).replace(/[^a-zA-Z0-9_:.-]/g, "_").slice(0,100);
});
